def maxDisjointProduct(nums):
    FULL = 4095
    present = set(nums)
    best = [-1] * 4096
    for v in present:
        best[v] = v
    for bit in range(12):
        for m in range(4096):
            if (m >> bit) & 1:
                if best[m ^ (1 << bit)] > best[m]:
                    best[m] = best[m ^ (1 << bit)]
    answer = 0
    for a in present:
        b = best[FULL ^ a]
        if b > 0:
            answer = max(answer, a * b)
    return answer
